//! Live Attr endpoints have zero length and their own tree root.
use super::*;
fn fixture()->(Document,Forms,Page){
 let mut d=crate::html::parse_loaded_document("<!doctype html><html><body><div id=root data-native=value>Unchanged</div><input id=neighbor value=seed></body></html>",&||Ok(())).unwrap();d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();p.set_location(&crate::navigation::address("https://attr-range.test/source",&crate::navigation::Location::home()).unwrap());assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);run(&mut d,&mut f,&mut p,"var root=document.getElementById('root'),attr=root.getAttributeNode('data-native'),r=document.createRange(),set=r.setStart,copy=r.cloneContents;r.selectNodeContents(root);");(d,f,p)
}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.begin_job();p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn range_attr_zero_length_independent_root_boundaries_queries_and_relative_errors(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
r.setStart(attr,0);if(r.startContainer!==attr||r.endContainer!==attr||r.startOffset||r.endOffset||!r.collapsed||r.commonAncestorContainer!==attr||r.toString()!==''||r.comparePoint(attr,0)!==0||!r.isPointInRange(attr,0)||!r.intersectsNode(attr)||r.intersectsNode(root))throw 'Attr is zero length independent tree root';var saved=r.cloneRange();if(saved.startContainer!==attr||saved.endContainer!==attr||!saved.collapsed||saved.compareBoundaryPoints(Range.START_TO_START,r)!==0||saved.toString()!=='')throw 'native independent Attr range clone';
var caught=0;for(var fn of [function(){r.setStart(attr,1);},function(){r.setEnd(attr,1);},function(){r.comparePoint(attr,1);},function(){r.isPointInRange(attr,1);}]){try{fn();}catch(e){if(e instanceof DOMException&&e.name==='IndexSizeError')caught++;}}if(caught!==4||r.startContainer!==attr||!r.collapsed)throw 'offset checked against Node length not attribute value';
caught=0;for(var name of ['setStartBefore','setStartAfter','setEndBefore','setEndAfter','selectNode']){try{r[name](attr);}catch(e){if(e instanceof DOMException&&e.name==='InvalidNodeTypeError')caught++;}}if(caught!==5||attr.ownerElement!==root||attr.parentNode!==null)throw 'ownerElement does not become tree parent';
r.setEnd(root,1);if(r.startContainer!==root||r.endContainer!==root||r.startOffset!==1||r.endOffset!==1||!r.collapsed)throw 'switch back to displayed tree root';r.selectNodeContents(attr);if(r.startContainer!==attr||r.endOffset||!r.collapsed)throw 'select Attr contents is collapsed';
var another=document.createAttribute('other'),outside=new Range();outside.selectNodeContents(another);caught=0;for(var fn of [function(){r.comparePoint(another,1);},function(){r.compareBoundaryPoints(Range.START_TO_START,outside);}]){try{fn();}catch(e){if(e instanceof DOMException&&e.name==='WrongDocumentError')caught++;}}if(caught!==2||r.isPointInRange(another,1)||r.intersectsNode(another)||r.startContainer!==attr)throw 'different Attr roots precede point-length validation';
"#);}
#[test]
fn range_attr_empty_contents_use_real_document_and_static_range_rejection_stays_distinct(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var owner=document.implementation.createHTMLDocument('source'),inert=owner.createAttribute('data-inert');inert.value='Not a child';for(var node of [attr,inert]){r.selectNodeContents(node);var a=r.cloneContents(),b=r.extractContents();if(a===b||a.nodeType!==11||b.nodeType!==11||a.ownerDocument!==node.ownerDocument||b.ownerDocument!==node.ownerDocument||a.firstChild!==null||b.firstChild!==null||r.deleteContents()!==undefined||r.startContainer!==node||!r.collapsed)throw 'empty native fragments retain real Attr owner';var failed=false;try{new StaticRange({startContainer:node,startOffset:0,endContainer:node,endOffset:0});}catch(e){failed=e instanceof DOMException&&e.name==='InvalidNodeTypeError';}if(!failed)throw 'StaticRange rejects Attr separately';}
r.selectNodeContents(attr);var caught=0;for(var fn of [function(){r.insertNode(document.createElement('i'));},function(){r.surroundContents(document.createElement('b'));}]){try{fn();}catch(e){if(e instanceof DOMException&&e.name==='HierarchyRequestError')caught++;}}if(caught!==2||r.startContainer!==attr||!r.collapsed||attr.value!=='value'||root.textContent!=='Unchanged')throw 'Attr cannot contain inserted children';
"#);}
#[test]
fn range_attr_value_attachment_and_owner_adoption_do_not_change_boundary_root(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
r.selectNodeContents(attr);var watch=new MutationObserver(function(){});watch.observe(root,{attributes:true,attributeOldValue:true});attr.value='A😀B';root.removeAttributeNode(attr);var next=document.createElement('span');next.setAttributeNode(attr);var records=watch.takeRecords();if(records.length!==2||records[0].oldValue!=='value'||records[1].oldValue!=='A😀B'||r.startContainer!==attr||r.endContainer!==attr||r.startOffset||r.endOffset||!r.collapsed||r.commonAncestorContainer!==attr||attr.ownerElement!==next)throw 'value and attachment preserve zero length independent Attr root';
var owner=new Document();owner.adoptNode(next);if(attr.ownerDocument!==owner||attr.ownerElement!==next||r.startContainer!==attr||r.commonAncestorContainer!==attr||r.comparePoint(attr,0)!==0||r.toString()!=='')throw 'actual owner adoption preserves Attr-root boundary';var clone=r.cloneContents(),extracted=r.extractContents();if(clone.ownerDocument!==owner||extracted.ownerDocument!==owner||clone.firstChild!==null||extracted.firstChild!==null)throw 'content factory follows current adopted Attr document';document.adoptNode(next);if(r.startContainer!==attr||r.cloneContents().ownerDocument!==document||r.extractContents().ownerDocument!==document)throw 'owner return retains native Range and fragment ownership';
"#);}
#[test]
fn range_attr_borrowed_method_authority_and_empty_factory_refusal_recovery(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var w=frame.contentWindow,foreignSet=w.Range.prototype.setStart;foreignSet.call(r,attr,0);if(r.startContainer!==attr||!r.collapsed)throw 'borrowed native Attr setter';");let before=(p.state.dom_commits,p.state.ranges[0].start,p.state.ranges[0].end);p.set_location(&crate::navigation::address("https://foreign.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();let error=p.runtime.execute("foreignSet.call(r,root,0)",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("origin"),"{error}");assert_eq!((p.state.dom_commits,p.state.ranges[0].start,p.state.ranges[0].end),before);p.set_location(&crate::navigation::address("https://attr-range.test/source",&crate::navigation::Location::home()).unwrap());run(&mut d,&mut f,&mut p,"foreignSet.call(r,attr,0);if(r.startContainer!==attr||!r.collapsed)throw 'Attr origin recovery';");
 for profile in 0..4{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"r.selectNodeContents(attr);");p.begin_job();let before=(d.nodes.len(),p.state.dom_commits,p.state.ranges[0].start,p.state.ranges[0].end);let limit=p.state.retained_limit;match profile{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,_=>{p.state.host_work=4096;p.state.execution_deadline=Some(Instant::now());}}assert!(p.runtime.execute("copy.call(r)",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).is_err());assert_eq!((d.nodes.len(),p.state.dom_commits,p.state.ranges[0].start,p.state.ranges[0].end),before);p.state.retained_limit=limit;run(&mut d,&mut f,&mut p,"var fragment=copy.call(r);if(fragment.ownerDocument!==document||fragment.firstChild!==null||r.startContainer!==attr||!r.collapsed||attr.value!=='value')throw 'empty Attr factory fresh recovery';");}
}
